import React, { useState } from 'react';
// Create the FileUpload component here
const FileUpload = () => {
  // Add useState for selectedFile here
  const [selectedFile, setSelectedFile] = useState(null);

  // Add useState for uploadProgress here
  const [uploadProgress, setUploadProgress] = useState(0);

  // Create handleFileChange function here
  const handleFileChange = (event) => {
    setSelectedFile(event.target.files[0]);
  };

  // Create handleUpload function here
  const handleUpload = () => {
    // Simulate upload progress
    let progress = 0;
    const interval = setInterval(() => {
      progress += 10;
      setUploadProgress(progress);
      if (progress >= 100) clearInterval(interval);
    }, 200);
  };

  return (
    <div>
      <input type="file" onChange={handleFileChange} />
      <button onClick={handleUpload}>Upload</button>
      {selectedFile && (
        <div>
          <p>Selected: {selectedFile.name} ({selectedFile.size} bytes)</p>
        </div>
      )}
      {/* Add progress bar here */}
    </div>
  );
};
